#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int main(void) {
    size_t cap = 16, len = 0;
    char *s = malloc(cap);
    if (!s) return 1;
    int c;
    while ((c = getchar()) != EOF) {
        if (isxdigit((unsigned char)c)) {
            if (len + 1 > cap) {
                cap *= 2;
                char *t = realloc(s, cap);
                if (!t) { free(s); return 1; }
                s = t;
            }
            s[len++] = (char)c;
        }
    }

    const unsigned BASE = 1000000000u;
    size_t bcap = 16, blen = 1;
    unsigned *b = calloc(bcap, sizeof *b);
    if (!b) { free(s); return 1; }

    for (size_t i = 0; i < len; i++) {
        char ch = s[i];
        unsigned d = (ch >= '0' && ch <= '9') ? (unsigned)(ch - '0') :
                    (ch >= 'a' && ch <= 'f') ? (unsigned)(ch - 'a' + 10) :
                    (unsigned)(ch - 'A' + 10);

        unsigned long long carry = 0;
        for (size_t j = 0; j < blen; j++) {
            unsigned long long x = (unsigned long long)b[j] * 16 + carry;
            b[j] = (unsigned)(x % BASE);
            carry = x / BASE;
        }
        while (carry) {
            if (blen == bcap) {
                bcap *= 2;
                unsigned *t = realloc(b, bcap * sizeof *b);
                if (!t) { free(b); free(s); return 1; }
                b = t;
            }
            b[blen++] = (unsigned)carry;
            carry /= BASE;
        }

        unsigned long long x = b[0] + d;
        b[0] = (unsigned)(x % BASE);
        carry = x / BASE;
        size_t j = 1;
        while (carry) {
            if (j == blen) {
                if (blen == bcap) {
                    bcap *= 2;
                    unsigned *t = realloc(b, bcap * sizeof *b);
                    if (!t) { free(b); free(s); return 1; }
                    b = t;
                }
                b[blen++] = 0;
            }
            unsigned long long y = b[j] + carry;
            b[j] = (unsigned)(y % BASE);
            carry = y / BASE;
            j++;
        }
    }

    printf("%u", b[blen - 1]);
    for (size_t i = blen - 1; i > 0; i--) {
        printf("%09u", b[i - 1]);
    }
    putchar('\n');

    free(b);
    free(s);
    return 0;
}

