#include <stdio.h>
#include <stdlib.h>

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static int partition(int *a, int l, int r) {
    int p = a[r], i = l - 1;
    for (int j = l; j < r; j++)
        if (a[j] <= p) { i++; swap(&a[i], &a[j]); }
    swap(&a[i + 1], &a[r]);
    return i + 1;
}

static void quicksort(int *a, int l, int r) {
    if (l < r) {
        int pi = partition(a, l, r);
        quicksort(a, l, pi - 1);
        quicksort(a, pi + 1, r);
    }
}

