#include <stdio.h>
#include <stdlib.h>

void merge(int *a, int *t, int l, int m, int r) {
    int i = l, j = m, k = l;
    while (i < m && j < r) t[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < m) t[k++] = a[i++];
    while (j < r) t[k++] = a[j++];
    for (i = l; i < r; i++) a[i] = t[i];
}

void msort(int *a, int *t, int l, int r) {
    if (r - l <= 1) return;
    int m = (l + r) / 2;
    msort(a, t, l, m);
    msort(a, t, m, r);
    merge(a, t, l, m, r);
}

